sys_ws_operation.operation_script:
// Scripted REST: POST /api/x_1821654_governa/ledger/runs
// v0.3 §4.3 / §8.2（2026-09-20 G）: 来歴列を作成時に確定する。
// 来歴が欠けた run は「どの版で何が起きたか」を説明できないため 400 で拒否する。
(function process(request, response) {
    var body = request.body.data || {};

    var required = ['task_id', 'agent', 'policy_set_hash', 'harness_commit', 'prompt_hash', 'tool_schema_hash'];
    var missing = [];
    for (var i = 0; i < required.length; i++) {
        if (!body[required[i]]) missing.push(required[i]);
    }
    if (missing.length) {
        response.setStatus(400);
        return { error: 'required: ' + missing.join(', ') };
    }
    var hex64 = /^[0-9a-f]{64}$/;
    var hashes = ['policy_set_hash', 'prompt_hash', 'tool_schema_hash'];
    for (var h = 0; h < hashes.length; h++) {
        if (!hex64.test(String(body[hashes[h]]))) {
            response.setStatus(400);
            return { error: hashes[h] + ' must be 64 lowercase hex chars' };
        }
    }

    var gr = new GlideRecord('x_1821654_governa_run');
    gr.initialize();
    gr.setValue('agent', body.agent);
    gr.setValue('task_id', body.task_id);
    gr.setValue('task_version', body.task_version || '');
    gr.setValue('seed', body.seed || '');
    gr.setValue('harness_version', body.harness_version || '');
    gr.setValue('harness_commit', body.harness_commit);
    gr.setValue('prompt_hash', body.prompt_hash);
    gr.setValue('tool_schema_hash', body.tool_schema_hash);
    gr.setValue('policy_set_hash', body.policy_set_hash);
    if (body.policy_snapshot_at) {
        var snap = new GlideDateTime();
        snap.setValue(String(body.policy_snapshot_at));   // UTC "YYYY-MM-DD HH:MM:SS"
        gr.setValue('policy_snapshot_at', snap);
    }
    if (body.eval_batch) gr.setValue('eval_batch', body.eval_batch);
    if (body.agent_version) gr.setValue('agent_version', body.agent_version);

    gr.setValue('started_at', new GlideDateTime());
    var sysId = gr.insert();
    if (!sysId) { response.setStatus(500); return { error: 'insert failed' }; }
    response.setStatus(201);
    return { sys_id: sysId, number: gr.getValue('number') };
})(request, response);
